const fs = require('fs');

(function main() {
  let raw;
  try {
    raw = fs.readFileSync(0, 'utf8');
  } catch (e) {
    raw = fs.readFileSync('/dev/stdin', 'utf8');
  }
  const tokens = raw.split(/\s+/).filter(Boolean);
  if (tokens.length < 2) {
    process.stdout.write('*\n');
    return;
  }
  const p = tokens[1];
  const n = p.length;

  // Contagens por prefixo: pc[(i*26)+c] = nº de ocorrências do caractere c em p[0..i-1]
  const pc = new Int32Array((n + 1) * 26);
  for (let i = 0; i < n; i++) {
    const prev = i * 26;
    const cur = prev + 26;
    for (let c = 0; c < 26; c++) pc[cur + c] = pc[prev + c];
    pc[cur + (p.charCodeAt(i) - 97)]++;
  }

  // Procura o menor d que divide n (com n/d >= 2) tal que todos os blocos
  // de comprimento d sejam anagramas entre si.
  const half = n >> 1;
  for (let d = 1; d <= half; d++) {
    if (n % d !== 0) continue;
    const bd = d * 26;
    const k = n / d;
    let ok = true;
    // Contagens do bloco 0 (referência): pc[bd + c] (prefixo na posição d menos posição 0)
    for (let j = 1; j < k; j++) {
      const s = j * bd;
      const e = s + bd;
      // basta comparar 25 caracteres: a soma das contagens de um bloco é sempre d
      for (let c = 0; c < 25; c++) {
        if (pc[e + c] - pc[s + c] !== pc[bd + c]) {
          ok = false;
          break;
        }
      }
      if (!ok) break;
    }
    if (ok) {
      process.stdout.write(p.slice(0, d) + '\n');
      return;
    }
  }
  process.stdout.write('*\n');
})();
